  ('Aşağıdaki tamlamalardan hangisi belirtisiz isim tamlamasıdır?', 'okul bahçesi', ['okulun bahçesi', 'büyük bahçe', 'bu bahçe'], 'Belirtisiz tamlamada tamlayan ek almaz, yalnız tamlanan iyelik eki alır: okul bahçe-si.'),
  ('İsim tamlamasında iyelik ekini taşıyan ve sahip olunan varlığı bildiren öge nasıl adlandırılır?', 'Tamlanan', ['Tamlayan', 'Niteleyen', 'Belirteç'], '\'Ali\'nin kalemi\' tamlamasında \'kalemi\' tamlanandır; ilgi ekini taşıyan \'Ali\'nin\' ise tamlayandır.'),
  ('Belirtili ve belirtisiz isim tamlaması arasındaki temel fark nedir?', 'Belirtilide tamlayan ilgi eki alır, belirtisizde almaz.', ['Belirtisizde tamlanan ek almaz.', 'Belirtilide yalnız tamlanan ek alır.', 'Belirtisiz tamlamada sıfat bulunur.'], '\'Kapının kolu\' belirtili, \'kapı kolu\' belirtisizdir; fark tamlayanın ekindedir.'),
  ('Varlıkların rengini, biçimini, durumunu bildiren sıfatlara ne ad verilir?', 'Niteleme sıfatı', ['Belirtme sıfatı', 'Belgisiz sıfat', 'İşaret sıfatı'], 'Kırmızı kalem, yuvarlak masa, yorgun adam: bunlar varlığın niteliğini bildiren niteleme sıfatlarıdır.'),
  ('"Yaşlı adam bankta oturuyordu." cümlesinde sıfat hangi işi görmektedir?', 'Adamın durumunu nitelemektedir.', ['Adamın yerini göstermektedir.', 'Adamın sayısını belirtmektedir.', 'Eylemin zamanını bildirmektedir.'], '\'Yaşlı\' sözcüğü adamın nasıl biri olduğunu anlatan niteleme sıfatıdır.'),
  ('"Sınıfın en çalışkan öğrencisi Elif\'tir." cümlesinde sıfata üstünlük anlamı katan sözcük hangisidir?', 'en', ['sınıfın', 'öğrencisi', 'Elif\'tir'], '\'En\' sözcüğü niteliğin bütün varlıklar içinde en üst düzeyde olduğunu bildirir.'),
  ('Varlıkları gösterme, sayı ya da soru yoluyla belirten sıfatlara ne ad verilir?', 'Belirtme sıfatı', ['Niteleme sıfatı', 'Adlaşmış sıfat', 'Pekiştirme sıfatı'], 'İşaret, sayı, belgisiz ve soru sıfatları belirtme sıfatlarıdır.'),
  ('"Şu kalemi bana uzatır mısın?" cümlesinde "şu" sözcüğünün türü hangisidir?', 'İşaret sıfatı', ['İşaret zamiri', 'Belgisiz sıfat', 'Soru sıfatı'], '\'Şu\' bir ismin (kalem) önüne gelerek onu göstermiştir; bu yüzden işaret sıfatıdır.'),
  ('"Öğrencilere beşer kalem dağıtıldı." cümlesindeki sayı sıfatının türü hangisidir?', 'Üleştirme sayı sıfatı', ['Sıra sayı sıfatı', 'Asıl sayı sıfatı', 'Kesir sayı sıfatı'], 'Beşer, her birine eşit pay verildiğini anlatan üleştirme sayı sıfatıdır.'),
  ('Aşağıdaki cümlelerin hangisinde belgisiz sıfat kullanılmıştır?', 'Bazı öğrenciler derse geç kaldı.', ['Bu öğrenciler çok çalışkan.', 'Üç öğrenci derse geç kaldı.', 'Hangi öğrenci geç kaldı?'], '\'Bazı\' sayısı ve kimliği belirsiz öğrencileri anlatır; belgisiz sıfattır.'),
  ('Aşağıdaki cümlelerin hangisinde asıl sayı sıfatı kullanılmıştır?', 'Masada yedi bardak vardı.', ['Yedinci sınıftayım.', 'Yedişer elma aldılar.', 'Yedide biri boştu.'], '\'Yedi\' varlığın sayısını doğrudan bildiren asıl sayı sıfatıdır.'),
  ('"Birçok" ve "birkaç" sözcükleri sıfat olarak kullanıldığında hangi türdedir?', 'Belgisiz sıfat', ['Asıl sayı sıfatı', 'Üleştirme sayı sıfatı', 'İşaret sıfatı'], 'Sayıyı belirsiz biçimde bildirdikleri için belgisiz sıfattırlar.'),
  ('Bir sıfatın bir ismi niteleyerek ya da belirterek oluşturduğu söz öbeğine ne ad verilir?', 'Sıfat tamlaması', ['İsim tamlaması', 'Zarf tümleci', 'İkileme'], 'Sıfat + isim yapısındaki öbekler sıfat tamlamasıdır: kırmızı elma, üç kitap.'),
  ('"Sapsarı" sözcüğünde sıfatın anlamı nasıl değişmiştir?', 'Niteliğin derecesi artırılmıştır.', ['Niteliğin derecesi azaltılmıştır.', 'Sıfat zarfa dönüşmüştür.', 'Sıfat isme dönüşmüştür.'], 'Sıfatın ilk hecesine p ünsüzü eklenip başa getirilerek niteliği güçlendirilmiştir.'),
  ('"Ben yarın geleceğim." cümlesindeki "ben" sözcüğü hangi zamir türündedir?', 'Kişi zamiri', ['İşaret zamiri', 'Belgisiz zamiri', 'Soru zamiri'], 'Ben, sen, o, biz, siz, onlar kişi adının yerini tutan kişi zamirleridir.'),
  ('"Şunu bana uzatır mısın?" cümlesindeki "şunu" sözcüğü hangi zamir türündedir?', 'İşaret zamiri', ['Kişi zamiri', 'Dönüşlülük zamiri', 'İlgi zamiri'], 'Şu, bu, o sözcükleri bir varlığı işaret ederek adının yerini tuttuğunda işaret zamiri olur.'),
  ('"Bu kitap çok güzel." cümlesindeki "bu" sözcüğü hangi türdedir?', 'İşaret sıfatı', ['İşaret zamiri', 'Kişi zamiri', 'Belgisiz zamir'], 'Bu burada "kitap" adını niteleyip belirttiği için sıfattır; adın yerini tutsaydı zamir olurdu.'),
  ('"Kimse bu işi yapmak istemedi." cümlesindeki "kimse" sözcüğü hangi zamir türündedir?', 'Belgisiz zamir', ['Soru zamiri', 'Üçüncü kişi zamiri', 'İşaret zamiri'], 'Kimse, kişi sayısını belirtmeksizin adın yerini tutan belgisiz bir zamirdir.'),
  ('"Kim geldi?" cümlesinde "kim" sözcüğü hangi zamir türündedir?', 'Soru zamiri', ['Belgisiz zamir', 'İşaret zamiri', 'İlgi zamiri'], 'Kim, ne, hangisi gibi sözcükler soru amacıyla adın yerini tuttuğunda soru zamiridir.'),
  ('Zarf, hangi sözcük türlerini niteleyerek anlamlarını durum, zaman, yer ve miktar yönünden etkiler?', 'Eylemleri, sıfatları ve zarfları', ['Yalnız adları ve adın yerini tutan zamirleri', 'Yalnız eylemleri ve ek eylemlerin kendilerini', 'Yalnız adları ve onları niteleyen sıfatları'], 'Zarflar eylemleri, sıfatları ve başka zarfları niteler; adları niteleyen sözcükler sıfattır.'),
  ('"Yarın erkenden kalkacağım." cümlesindeki "yarın" sözcüğü hangi zarf türündedir?', 'Zaman zarfı', ['Durum zarfı', 'Yer-yön zarfı', 'Miktar zarfı'], 'Yarın, eylemin ne zaman yapılacağını bildirdiğinden zaman zarfıdır.'),
  ('"Çocuklar dışarı koştu." cümlesindeki "dışarı" sözcüğü hangi zarf türündedir?', 'Yer-yön zarfı', ['Zaman zarfı olarak kullanılmıştır', 'Durum zarfı olarak kullanılmıştır', 'Soru zarfı olarak kullanılmıştır'], 'Dışarı, eylemin yönünü bildirdiği için yer-yön zarfıdır.'),
  ('"Arkadaşım hızlı konuşuyor." cümlesindeki "hızlı" sözcüğü hangi zarf türündedir?', 'Durum zarfı', ['Zaman zarfı', 'Miktar zarfı', 'Yer-yön zarfı'], 'Hızlı, eylemin nasıl yapıldığını bildirdiğinden durum (niteleme) zarfıdır.'),
  ('"Bu çorbayı biraz tuzlu buldum." cümlesindeki "biraz" sözcüğü hangi zarf türündedir?', 'Miktar zarfı', ['Zaman zarfı', 'Durum (niteleme) zarfı', 'Soru zarfı'], 'Biraz, "tuzlu" sıfatının derecesini bildirdiği için miktar zarfıdır.'),
  ('Edatlar (ilgeçler) için aşağıdakilerden hangisi doğrudur?', 'Tek başına anlamı olmayıp başka sözcüklerle anlam kazanırlar', ['Her zaman eylemlerin sonuna eklenerek kullanılırlar', 'Cümlede tek başlarına yüklem olabilirler', 'Adların yerine geçip ad gibi ek alırlar'], 'Edatlar sözcükler arasında anlam ilgisi kuran, yalın hâlde kullanıldığında ancak başka sözcüklerle anlam kazanan sözcüklerdir.'),
  ('"Bu hediye senin için." cümlesindeki "için" sözcüğü hangi türdedir?', 'Edat', ['Bağlaç', 'Zarf', 'Zamir'], 'İçin, "senin" ile birlikte amaç ya da fayda ilgisi kuran bir edattır.'),
  ('"Kuş gibi uçtu." cümlesindeki "gibi" sözcüğü hangi anlam ilgisini kurar?', 'Benzetme', ['Neden', 'Amaç', 'Karşıtlık'], 'Gibi, kuş ile uçma arasında benzetme ilgisi kurar.'),
  ('Aşağıdakilerden hangisi bağlaçların görevidir?', 'Sözcükleri ya da cümleleri birbirine bağlamak', ['Adların yerine geçerek özne ya da nesne olmak', 'Eylemin zamanını ve kişisini bildirmek', 'Adları niteleyerek anlamlarını sınırlayıp belirtmek'], 'Bağlaçlar tek başlarına anlamı zayıf olan, sözcükleri ve cümleleri birbirine bağlayan sözcüklerdir.'),
  ('"Hava soğuktu ama dışarı çıktık." cümlesindeki "ama" bağlacı hangi anlam ilişkisini kurar?', 'Karşıtlık', ['Neden bildirme ve açıklama', 'Seçenek ve tercih sunma', 'Ekleme ve sıralama'], 'Ama, iki yargı arasında karşıtlık ilişkisi kurar.'),
  ('"Kitap okurum çünkü öğrenmeyi severim." cümlesindeki "çünkü" bağlacının kurduğu ilişki hangisidir?', 'Neden-sonuç', ['Karşıtlık ve zıtlık', 'Seçenek ve tercih', 'Ekleme ve birleştirme'], 'Çünkü, birinci cümlenin nedenini açıklayan ikinci cümleyi birinciye bağlar.'),
  ('"Çay mı içersin yoksa kahve mi?" cümlesinde "yoksa" hangi türdedir?', 'Bağlaç', ['Edat olarak kullanılmıştır', 'Zarf olarak kullanılmıştır', 'Zamir olarak kullanılmıştır'], 'Yoksa, seçenek bildiren iki ögeyi birbirine bağlar.'),
  ('"Ya sen gelirsin ya da ben giderim." cümlesindeki "ya … ya da" bağlacı ne anlam verir?', 'Seçenek', ['Karşıtlık', 'Neden', 'Ekleme'], 'Ya … ya da, iki seçenekten birinin olacağını belirtir.'),
  ('Sözcük türleri içinde yer alan ünlem hangi tanıma uyar?', 'Duyguyu ya da seslenmeyi anlatan sözcük', ['Eylemin zamanını ve kişisini bildiren sözcük', 'Adların yerine geçip ek alabilen sözcük', 'İki cümleyi birbirine bağlayıp ilişki kuran sözcük'], 'Ünlemler duygu ve heyecanı bildiren ya da seslenme amacıyla kullanılan sözcüklerdir.'),
  ('"Of, yine yağmur başladı!" cümlesinde "of" sözcüğü hangi türdedir?', 'Ünlem', ['Bağlaç', 'Edat', 'Zarf'], 'Of, bıkkınlık ve sıkıntı duygusunu anlatan bir ünlemdir.'),
  ('"Eyvah! Anahtarı unutmuşum." cümlesinde "eyvah" hangi duyguyu anlatır?', 'Korku ya da pişmanlık', ['Sevinç ve coşku duygusu', 'Hayranlık ve beğeni duygusu', 'Alay ve küçümseme duygusu'], 'Eyvah, kötü bir durumla karşılaşıldığında duyulan telaş ve pişmanlığı anlatır.'),
  ('"Yaşasın! Kupayı biz kazandık." cümlesindeki "yaşasın" sözcüğü hangi duyguyu bildirir?', 'Sevinç', ['Üzüntü ve acı', 'Korku ve çekinme', 'Öfke ve kızgınlık'], 'Yaşasın, sevinç ve coşkuyu anlatan ünlemdir.'),
  ('Aşağıdakilerden hangisi eylemin gelecekte gerçekleşeceğini bildiren kip ekidir?', '-acak / -ecek', ['-mış / -miş', '-dı / -di', '-yor'], 'Gelecek zaman eki -acak/-ecek\'tir; -di görülen, -miş öğrenilen geçmiş, -yor şimdiki zamandır.'),
  ('"Dün akşam arkadaşımla sinemaya gittik." cümlesindeki eylem hangi kiptedir?', 'Görülen geçmiş zaman', ['Öğrenilen geçmiş zaman kipi', 'Geniş zaman kipi', 'Gelecek zaman kipi'], 'Gittik, -di ekiyle kurulmuş ve eylemin bizzat yapıldığını bildiren görülen geçmiş zamandır.'),
  ('"Bana söylediğine göre dün çok yağmur yağmış." cümlesindeki "yağmış" hangi kiptedir?', 'Öğrenilen geçmiş zaman', ['Görülen geçmiş zaman kipi', 'Şimdiki zaman kipi', 'Gelecek zaman kipi'], '-miş eki, eylemin sonradan öğrenildiğini ya da başkasından duyulduğunu bildirir.'),
  ('"Çocuklar bahçede oynuyor." cümlesindeki eylem hangi kiptedir?', 'Şimdiki zaman', ['Geniş zaman', 'Gelecek zaman', 'Öğrenilen geçmiş zaman'], '-yor eki, eylemin şu anda sürdüğünü bildirir.'),
  ('Hangi kip eki, eylemin işin yapıldığı anda sürdüğünü bildirir?', '-yor', ['-ecek', '-miş', '-meli'], '-yor şimdiki zaman eki olup eylemin konuşma anında devam ettiğini bildirir.'),
  ('Dilek kiplerinden hangisi bir şeyin yapılması gerektiğini bildirir?', 'Gereklilik kipi', ['İstek kipi', 'Koşul kipi', 'Emir kipi'], 'Gereklilik kipi eki -malı/-meli olup "yapmalı" gibi gereksinim anlatır.'),
  ('"Hadi, birlikte çalışalım." cümlesindeki "çalışalım" hangi kiptedir?', 'İstek kipi', ['Emir kipi', 'Koşul kipi', 'Gereklilik kipi'], '-ayım, -alım, -elim ekleriyle kurulan fiiller istek kipindedir.'),
  ('"Hava güzel olsa bahçeye çıkarız." cümlesindeki "olsa" hangi kiptedir?', 'Koşul kipi', ['İstek kipi', 'Gereklilik kipi', 'Geniş zaman kipi'], '-sa/-se eki, bir eylemin gerçekleşmesini başka bir eylemin gerçekleşmesine bağlayan koşul kipidir.'),
  ('"Hemen odana git!" cümlesindeki eylem hangi kiptedir?', 'Emir kipi', ['Gereklilik kipi', 'İstek kipi', 'Koşul kipi'], 'İkinci tekil kişide eksiz kullanılan git, bir işin yapılması için verilen emri bildirir.'),
  ('Birleşik zamanlı eylemlerde basit zamanlı eyleme eklenen ek eylem ekleri hangileridir?', '-di, -miş, -se (idi, imiş, ise)', ['-yor, -ecek ve -meli ekleri (kip ekleri)', '-ma, -me ve -mez ekleri (olumsuzluk ekleri)', '-ken, -ince ve -erek ekleri (zarf-fiil ekleri)'], 'Hikâye (-di), rivayet (-miş) ve şart (-se) birleşik zamanları, basit zamanlı eyleme ek eylemin bu biçimlerinin gelmesiyle kurulur.'),
  ('"Biz o sırada yemek yiyorduk." cümlesindeki "yiyorduk" hangi birleşik zamandadır?', 'Şimdiki zamanın hikâyesi', ['Şimdiki zamanın rivayeti olarak', 'Geniş zamanın şartı olarak', 'Gelecek zamanın hikâyesi olarak'], 'Yi-yor-du-k, şimdiki zaman eki -yor üzerine hikâye eki -du eklenerek kurulmuştur.'),
  ('"Annem ev işlerini bitirmişti." cümlesindeki "bitirmişti" hangi birleşik zamandadır?', 'Öğrenilen geçmişin hikâyesi', ['Görülen geçmiş zamanın rivayeti', 'Şimdiki zamanın şartı olarak', 'Gelecek zamanın hikâyesi olarak'], 'Bitir-miş-ti: -miş eki üzerine hikâye eki -ti gelmiştir.'),
  ('Ek eylem ya da ek fiil, aşağıdakilerden hangisi için kullanılır?', 'Ad soylu sözcükleri yüklem yapmak', ['Eylemlerin köklerini ve gövdelerini değiştirmek', 'Adlar arasında benzetme ve karşılaştırma yapmak', 'Cümleler arasında bağ kurup ilişkiyi göstermek'], 'Ek eylem, ad soylu sözcüklere gelerek onları yüklem yapar ve zaman ile kişi bildirir.'),
  ('"Annem öğretmendir." cümlesindeki "-dir" eki hangi işlevi görür?', 'Ad soylu sözcüğü yüklem yapar', ['Sözcüğü eylemden ada çevirir ve türetir', 'Sözcüğe benzetme anlamı katıp niteler', 'Sözcüğü çoğul yapıp nicelik bildirir'], '-dir, ek eylemin geniş zaman biçimidir ve "öğretmen" adını yüklem yapar.'),
  ('"Hava dün çok güzeldi." cümlesindeki "-di" eki hangi türdendir?', 'Ek eylemin hikâye biçimi', ['Görülen geçmiş zaman kip eki', 'Yapım eki', 'Çoğul eki'], 'Güzel-di\'deki -di, ad soylu sözcüğe gelmiş ek eylemin hikâye biçimidir.'),
  ('Özne bakımından eylemin çatıları hangileridir?', 'Etken, edilgen, dönüşlü, işteş', ['Geçişli, geçişsiz, yapım, çekim', 'Olumlu, olumsuz, soru, emir', 'Basit, türemiş, birleşik, kalıplaşmış'], 'Çatı, eylemin özneye göre aldığı durumdur: etken, edilgen, dönüşlü ve işteş. Geçişlilik nesneye göre belirlenir.'),
  ('"Mektup yazıldı." cümlesinde eylemin çatısı nedir?', 'Edilgen', ['Etken çatılıdır', 'Dönüşlü çatılıdır', 'İşteş çatılıdır'], 'Yazıldı, -ıl ekiyle edilgen yapılmıştır; öznesi belli olmayan bir iş anlatır.'),
  ('"Küçük çocuk sabah giyindi." cümlesindeki "giyindi" hangi çatıdadır?', 'Dönüşlü', ['Edilgen', 'Ettirgen', 'İşteş'], 'Giy-in-di: -in eki, işin öznenin kendisine dönük yapıldığını bildirir.'),
  ('"İki arkadaş sevinçle kucaklaştı." cümlesindeki "kucaklaştı" hangi çatıdadır?', 'İşteş', ['Dönüşlü', 'Edilgen', 'Ettirgen'], 'Kucakla-ş-tı: -ş eki, işin karşılıklı ya da birlikte yapıldığını bildirir.'),
  ('Fiilimsi (eylemsi) nedir?', 'Eylemden türeyip ad, sıfat ya da zarf olan sözcük', ['Hâl eki alarak ad soylu olan, çekimli sözcük', 'Cümleye zaman ve kişi katan ek eylem sözcüğü', 'Başka sözcüklerle bağ kuran, ilgi bildiren edat sözcüğü'], 'Fiilimsiler eylem kök ya da gövdesinden türer; ad, sıfat ve zarf gibi kullanılır, ancak kip ve kişi eki almazlar.'),
  ('İsim-fiil (ad-eylem) ekleri aşağıdakilerden hangileridir?', '-mek, -me, -iş', ['-an, -dık, -ecek', '-ip, -erek, -ince', '-yor, -miş, -di'], '-mak/-mek, -ma/-me ve -ış/-iş ekleri eylemden ad-eylem (isim-fiil) türetir.'),
  ('"Okumak insanı geliştirir." cümlesindeki "okumak" sözcüğü hangi fiilimsidir?', 'İsim-fiil', ['Sıfat-fiil', 'Zarf-fiil', 'Edilgen fiil'], 'Okumak, -mak ekiyle kurulmuş ve cümlede özne olmuş bir isim-fiildir.'),
  ('"Yarışa gidişini hiç unutmam." cümlesindeki "gidişini" sözcüğü hangi fiilimsidir?', 'İsim-fiil', ['Sıfat-fiil', 'Zarf-fiil', 'Edat'], 'Git-iş-i-ni, -iş ekiyle kurulmuş ve hâl eki alarak nesne olmuş isim-fiildir.'),
  ('Aşağıdaki eklerden hangisi sıfat-fiil (ortaç) eki değildir?', '-erek', ['-an ve -en', '-dık ve -dik', '-ecek ve -acak'], '-erek zarf-fiil ekidir. -an/-en, -dık/-dik ve -ecek/-acak sıfat-fiil ekleridir.'),
  ('"Gelen misafirleri sevinçle karşıladık." cümlesinde "gelen" sözcüğü hangi türdedir?', 'Sıfat-fiil', ['İsim-fiil olarak kullanılmıştır', 'Zarf-fiil olarak kullanılmıştır', 'Edat olarak kullanılmıştır'], 'Gel-en, "misafirleri" adını niteleyen sıfat-fiildir.'),
  ('"Çocuk koşarak okula geldi." cümlesinde "koşarak" hangi fiilimsidir?', 'Zarf-fiil', ['İsim-fiil', 'Sıfat-fiil', 'Ünlem'], 'Koş-arak, "geldi" eylemini niteleyen zarf-fiildir.'),
  ('"Eve gelince beni ara." cümlesindeki "gelince" sözcüğü hangi fiilimsidir?', 'Zarf-fiil', ['Sıfat-fiil', 'İsim-fiil', 'Ek eylem'], 'Gel-ince, "ara" eyleminin zamanını bildiren zarf-fiildir.'),
  ('Aşağıdakilerden hangisi pekiştirmeli bir sözcüktür?', 'bembeyaz', ['güzel güzel', 'ders mers', 'aşağı yukarı'], 'Bembeyaz, "be" hecesine m ünsüzü eklenerek yapılmış pekiştirmeli sıfattır. Diğerleri ikilemedir.'),
  ('"Masmavi" sözcüğündeki pekiştirme hangi ses ile kurulmuştur?', 's', ['m ünsüzü ile', 'p ünsüzü ile', 'r ünsüzü ile'], 'Mavi sözcüğünün ilk hecesi "ma" alınmış ve araya s eklenmiştir: ma-s-mavi.'),
  ('"Kıpkırmızı" sözcüğündeki pekiştirme hecesi hangisidir?', 'kıp', ['kırk', 'mız', 'kırm'], 'Kırmızı sözcüğünün ilk hecesi (kı) alınmış, p ünsüzü eklenmiştir: kıp-kırmızı.'),
  ('"Şakır şakır yağmur yağıyor." cümlesindeki "şakır şakır" sözcüğü hangi türdendir?', 'Yansımalı ikileme', ['Pekiştirmeli sıfat', 'Zıt anlamlı ikileme', 'm\'li ikileme'], 'Şakır şakır, yağmurun sesini taklit ettiği için yansımalı ikilemedir.'),
  ('"Ders mers çalışmadı." sözcüklerindeki ikileme türü hangisidir?', 'm\'li ikileme', ['Pekiştirme', 'Zıt anlamlı ikileme', 'Eş anlamlı ikileme'], 'Ders mers, ikinci sözcüğün m ile başlayarak anlam genişliği yarattığı ikilemedir.'),
  ('Eylemlerde olumsuzluk eki hangisidir?', '-ma / -me', ['-yor / -iyor', '-miş / -muş', '-ip / -ıp'], 'Eylem kök ya da gövdesine -ma/-me eki getirilerek olumsuz yapılır.'),
  ('"Okula gitmedi." cümlesinde "gitmedi" eylemi ne anlam taşır?', 'Olumsuz görülen geçmiş', ['Olumlu görülen geçmiş zaman', 'Olumsuz gelecek zaman', 'Olumlu geniş zaman'], 'Git-me-di, olumsuzluk eki -me ile görülen geçmiş zaman eki -di\'den oluşur.'),
  ('"Bu işi sen yapma!" cümlesindeki "yapma" sözcüğü neyi bildirir?', 'Olumsuz emir', ['Olumlu emir', 'İsim-fiil', 'Olumsuz gelecek zaman'], 'Yap-ma, ikinci tekil kişiye emir verirken olumsuzluk ekiyle kurulmuş olumsuz emir biçimidir.'),
  ('"Yaz" sözcüğü hangi cümlede ad olarak kullanılmıştır?', 'Bu yaz tatile çıkacağız.', ['Mektubu hemen yaz da gönder.', 'Ödevini defterine kalemle yaz.', 'Adını şuraya büyük harfle yaz.'], 'Birinci cümlede yaz mevsim adıdır; öbür cümlelerde yazmak eyleminin emir kipidir.'),
  ('Yağış olayını anlatan bir ad olarak kullanılan "dolu" hangi cümlede geçer?', 'Dün akşam şiddetli dolu yağdı.', ['Dolu bir bardak su içiverdi.', 'Salon bu akşam tamamen dolu çıktı.', 'Torba bana yine ağzına kadar dolu göründü.'], 'Birinci cümlede dolu, yağış adıdır; diğerlerinde bir nesnenin durumunu niteleyen sıfat ya da yüklemdir.'),
  ('"Yardım etmek" ve "kabul etmek" birleşik eylemleri hangi yolla oluşmuştur?', 'Ad + yardımcı eylem birleşmesiyle', ['Eylem + eylem kaynaşmasıyla', 'Sıfat-fiil + ad birleşmesiyle', 'Yapım ekinin eklenmesiyle ve kök değişmesiyle'], 'Yardım ve kabul adları, "etmek" yardımcı eylemiyle birleşerek birleşik eylem kurmuştur.'),
  ('"Bu soruyu çözebilirim." cümlesindeki "çözebilirim" sözcüğünde hangi birleşik eylem türü vardır?', 'Yeterlik', ['Tezlik birleşik eylemi olarak', 'Sürerlik birleşik eylemi olarak', 'Yaklaşma birleşik eylemi olarak'], '-ebil- eki, eylemin yapılabileceğini bildirir: yeterlik.'),
  ('"Mektubu hemen yazıverdi." cümlesindeki "yazıverdi" hangi birleşik eylem türündedir?', 'Tezlik', ['Yeterlik', 'Sürerlik', 'Yaklaşma'], '-iver- eki, işin hemen, çabucak yapıldığını bildirir: tezlik.'),
  ('Türkçenin eklemeli (bitişken) bir dil olması ne anlama gelir?', 'Kökün eklerle yeni görev almasıdır', ['Sözcüklerin ünlü değişimiyle çekimlenmesidir', 'Her anlamın ayrı bir sözcükle verilmesidir', 'Eklerin sözcüğün başına getirilmesidir'], 'Türkçede kök genellikle korunur; ekler art arda eklenerek yeni sözcük ve görevler kurar.'),
  ('"Evlerimizden" sözcüğünde kaç ek bulunur?', 'Üç ek', ['İki ek bulunur', 'Dört ek bulunur', 'Yalnızca bir ek bulunur'], 'Ev-ler-imiz-den: çoğul, iyelik ve ayrılma hâli olmak üzere üç ek vardır.'),
  ('"Okulun bahçesinde çiçekler açtı." cümlesindeki "çiçekler" sözcüğü hangi türdedir?', 'Ad', ['Sıfat olarak kullanılmıştır', 'Zarf olarak kullanılmıştır', 'Zamir olarak kullanılmıştır'], 'Çiçekler, bir varlığı karşılayan ve çoğul eki almış addır.'),
  ('"Mavi kazak sana çok yakışmış." cümlesinde "mavi" hangi türdedir?', 'Sıfat', ['Ad olarak kullanılmıştır', 'Zarf olarak kullanılmıştır', 'Zamir olarak kullanılmıştır'], 'Mavi, "kazak" adını niteleyen niteleme sıfatıdır.'),
  ('"O, akşam eve geldi." cümlesindeki "o" sözcüğü hangi türdedir?', 'Zamir', ['Sıfat olarak kullanılmıştır', 'Edat olarak kullanılmıştır', 'Zarf olarak kullanılmıştır'], 'O, kişi adının yerini tutan kişi zamiridir.'),
  ('Aşağıdaki sözcük türlerinden hangisi ad soylu kabul edilmez?', 'Eylem', ['Ad (isim) türü', 'Sıfat türü', 'Zamir türü'], 'Eylemler eylem soylu sözcüklerdir; ad, sıfat ve zamir ad soylu olarak sınıflandırılır.'),
  ('Kendi başlarına anlamları olmayıp cümlede başka sözcüklere bağlanarak görev yapan sözcük türleri hangileridir?', 'Edat ve bağlaç', ['Ad ve sıfat türleri', 'Zamir ve zarf türleri', 'Eylem ve ünlem türleri'], 'Edat ve bağlaç, sözcükler ve cümleler arasında ilgi ve bağ kuran yardımcı sözcüklerdir.'),
];
